import { decodePixels, ProtocolError } from './qr';

export function cameraError(error: unknown): string {
  if (error instanceof ProtocolError) return error.key;
  if (error instanceof DOMException) {
    if (error.name === 'NotAllowedError' || error.name === 'SecurityError') return 'cameraDenied';
    if (error.name === 'NotFoundError' || error.name === 'OverconstrainedError') return 'cameraMissing';
    if (error.name === 'NotReadableError' || error.name === 'AbortError') return 'cameraBusy';
  }
  return 'cameraFailed';
}

/** Owns only its scanner stream; a preview CSS transform never changes decoder pixels. */
export class Scanner {
  private stream: MediaStream | null = null;
  private readonly canvas = document.createElement('canvas');
  private readonly context = this.canvas.getContext('2d', { willReadFrequently: true });
  private animation: number | null = null;
  private videoFrame: number | null = null;
  private generation = 0;
  private lastDecode = 0;
  private busy = false;
  constructor(private readonly video: HTMLVideoElement,
    private readonly onFrame: (bytes: Uint8Array) => Promise<void> | void,
    private readonly onError: (key: string) => void) {}

  static async cameras(): Promise<MediaDeviceInfo[]> {
    if (!navigator.mediaDevices?.enumerateDevices) return [];
    return (await navigator.mediaDevices.enumerateDevices()).filter(device => device.kind === 'videoinput');
  }
  async start(deviceId?: string): Promise<void> {
    this.stop();
    const generation = this.generation;
    try {
      if (!isSecureContext) throw new ProtocolError('insecure');
      if (!navigator.mediaDevices?.getUserMedia || !this.context) throw new ProtocolError('unsupported');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: false, video: deviceId
        ? { deviceId: { exact: deviceId }, width: { ideal: 1280 }, height: { ideal: 720 } }
        : { facingMode: { ideal: 'environment' }, width: { ideal: 1280 }, height: { ideal: 720 } } });
      if (generation !== this.generation) { stream.getTracks().forEach(track => track.stop()); return; }
      this.stream = stream;
      this.video.srcObject = stream; this.video.muted = true; this.video.playsInline = true;
      await this.video.play();
      if (generation !== this.generation) return;
      this.lastDecode = Number.NEGATIVE_INFINITY;
      const useVideoFrames = typeof this.video.requestVideoFrameCallback === 'function'
        && typeof this.video.cancelVideoFrameCallback === 'function';
      const scheduleFrame = (): void => {
        if (generation !== this.generation) return;
        // Follow actual camera frames where available rather than polling the
        // display refresh rate. Keep the existing fallback for older browsers.
        if (useVideoFrames) this.videoFrame = this.video.requestVideoFrameCallback(tick);
        else this.animation = requestAnimationFrame(tick);
      };
      const tick = (now: number): void => {
        if (generation !== this.generation) return;
        this.animation = null; this.videoFrame = null;
        scheduleFrame();
        if (this.busy || now - this.lastDecode < 180 || this.video.readyState < 2 || !this.video.videoWidth) return;
        this.lastDecode = now;
        const scale = Math.min(1, 960 / this.video.videoWidth);
        const width = Math.round(this.video.videoWidth * scale), height = Math.round(this.video.videoHeight * scale);
        // Assigning even an unchanged canvas dimension resets its backing store.
        if (this.canvas.width !== width) this.canvas.width = width;
        if (this.canvas.height !== height) this.canvas.height = height;
        this.context!.drawImage(this.video, 0, 0, this.canvas.width, this.canvas.height);
        const bytes = decodePixels(this.context!.getImageData(0, 0, this.canvas.width, this.canvas.height));
        if (!bytes) return;
        this.busy = true;
        Promise.resolve().then(() => {
          if (generation === this.generation) return this.onFrame(bytes);
        }).catch(error => {
          if (generation === this.generation) this.onError(error instanceof ProtocolError ? error.key : 'qrInvalid');
        }).finally(() => { if (generation === this.generation) this.busy = false; });
      };
      // play() can resolve after the first frame was already presented. Decode
      // that ready frame once: a static capture may never produce another one.
      tick(performance.now());
    } catch (error) {
      if (generation !== this.generation) return;
      this.stop(); const key = cameraError(error); this.onError(key); throw new ProtocolError(key);
    }
  }
  stop(): void {
    this.generation++;
    if (this.animation !== null) cancelAnimationFrame(this.animation);
    if (this.videoFrame !== null) this.video.cancelVideoFrameCallback(this.videoFrame);
    this.animation = null; this.videoFrame = null; this.busy = false;
    const owned = this.stream; this.stream = null;
    owned?.getTracks().forEach(track => track.stop());
    if (owned && this.video.srcObject === owned) { this.video.pause(); this.video.srcObject = null; }
    this.canvas.width = 0; this.canvas.height = 0;
  }
}
