function preference(key: string): string | null { try { return localStorage.getItem(key); } catch { return null; } }
export let language: 'en' | 'fr' = preference('qr-link-language') === 'fr' || (!preference('qr-link-language') && navigator.language.startsWith('fr')) ? 'fr' : 'en';
export function t(key: string): string { return (language === 'fr' ? fr : en)[key as Key] ?? (language === 'fr' ? fr.unknownError : en.unknownError); }
export function setLanguage(value: 'en' | 'fr'): void { language = value; try { localStorage.setItem('qr-link-language', value); } catch { /* Preferences are optional. */ } document.documentElement.lang = value; }
export function translate(): void {
  if (document.documentElement.lang !== language) document.documentElement.lang = language;
  const title = t('appTitle');
  if (document.title !== title) document.title = title;
  document.querySelectorAll<HTMLElement>('[data-i18n]').forEach(el => {
    const text = t(el.dataset.i18n!);
    if (el.textContent !== text) el.textContent = text;
  });
  document.querySelectorAll<HTMLElement>('[data-label]').forEach(el => {
    const label = t(el.dataset.label!);
    if (el.getAttribute('aria-label') !== label) el.setAttribute('aria-label', label);
  });
}
export function size(bytes: number): string { const units = language === 'fr' ? ['o', 'Kio', 'Mio', 'Gio'] : ['B', 'KiB', 'MiB', 'GiB']; const power = Math.min(3, Math.max(0, Math.floor(Math.log(bytes || 1) / Math.log(1024)))); return `${new Intl.NumberFormat(language, { maximumFractionDigits: power ? 1 : 0 }).format(bytes / 1024 ** power)} ${units[power]}`; }
export { en, fr };
