import QRCode, { type QRCodeSegment } from 'qrcode';
import jsQR from 'jsqr';
import { deflateSync, inflateSync } from 'fflate';

export const QR_VERSION = 1;
export const HEADER_BYTES = 72;
export const MAX_COMPRESSED_BYTES = 65_536;
export const MAX_JSON_BYTES = 262_144;
export const MAX_FRAMES = 64;
export const PENDING_MS = 600_000;
const MAX_CLOCK_SKEW_MS = 120_000;
const MAGIC = Uint8Array.of(0x51, 0x52, 0x4c, 0x4b);

export type PairingKind = 'offer' | 'answer';
export interface PairingEnvelope {
  v: 1;
  kind: PairingKind;
  session: string;
  created: number;
  expires: number;
  description: { type: PairingKind; sdp: string };
  offerDigest?: string;
}
export interface PairingStats { jsonBytes: number; compressedBytes: number; framedBytes: number }
export interface EncodedPairing {
  frames: Uint8Array[];
  digest: string;
  stats: PairingStats;
}
export class ProtocolError extends Error {
  constructor(public readonly key: string) { super(key); this.name = 'ProtocolError'; }
}
export const bytesToHex = (bytes: Uint8Array): string => Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
export function hexToBytes(value: string, length: number): Uint8Array {
  if (!new RegExp(`^[0-9a-f]{${length * 2}}$`).test(value)) throw new ProtocolError('qrInvalid');
  return Uint8Array.from({ length }, (_, i) => Number.parseInt(value.slice(i * 2, i * 2 + 2), 16));
}
export function randomId(): string { return bytesToHex(crypto.getRandomValues(new Uint8Array(16))); }
export async function sha256(bytes: Uint8Array): Promise<Uint8Array> {
  return new Uint8Array(await crypto.subtle.digest('SHA-256', Uint8Array.from(bytes).buffer));
}
function equal(a: Uint8Array, b: Uint8Array): boolean {
  return a.length === b.length && a.every((value, i) => value === b[i]);
}
function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

export function validateEnvelope(value: unknown, now = Date.now()): PairingEnvelope {
  if (!record(value) || value.v !== QR_VERSION) throw new ProtocolError(record(value) && 'v' in value ? 'qrUnsupported' : 'qrInvalid');
  if (value.kind !== 'offer' && value.kind !== 'answer') throw new ProtocolError('qrInvalid');
  if (typeof value.session !== 'string' || !/^[0-9a-f]{32}$/.test(value.session)) throw new ProtocolError('qrInvalid');
  if (!Number.isSafeInteger(value.created) || !Number.isSafeInteger(value.expires)) throw new ProtocolError('qrInvalid');
  const created = value.created as number, expires = value.expires as number;
  if (created <= 0 || expires <= created || expires - created > PENDING_MS) throw new ProtocolError('qrInvalid');
  if (created > now + MAX_CLOCK_SKEW_MS || expires < now - 86_400_000) throw new ProtocolError('qrClockSkew');
  if (expires <= now) throw new ProtocolError('qrExpired');
  if (!record(value.description) || value.description.type !== value.kind || typeof value.description.sdp !== 'string'
    || value.description.sdp.length === 0 || value.description.sdp.length > MAX_JSON_BYTES) throw new ProtocolError('qrInvalid');
  if (value.kind === 'answer' && (typeof value.offerDigest !== 'string' || !/^[0-9a-f]{64}$/.test(value.offerDigest))) throw new ProtocolError('qrInvalid');
  if (value.kind === 'offer' && value.offerDigest !== undefined) throw new ProtocolError('qrInvalid');
  return value as unknown as PairingEnvelope;
}

/** node-qrcode 1.5.4 accepts typed bytes; @types/qrcode still declares only strings.
 * This assertion is confined to the documented byte-segment API. It never converts bytes to text. */
export function byteSegments(bytes: Uint8Array): QRCodeSegment[] {
  return [{ data: bytes, mode: 'byte' }] as unknown as QRCodeSegment[];
}
export function qrSymbol(bytes: Uint8Array): ReturnType<typeof QRCode.create> {
  if (bytes.length === 0 || bytes.length > 2_953) throw new ProtocolError('qrTooLarge');
  try { return QRCode.create(byteSegments(bytes), { errorCorrectionLevel: 'L' }); }
  catch { throw new ProtocolError('qrTooLarge'); }
}
export async function renderQr(canvas: HTMLCanvasElement, bytes: Uint8Array): Promise<void> {
  const symbol = qrSymbol(bytes);
  // Integral module size, four opaque white quiet-zone modules on every side.
  const scale = Math.max(3, Math.min(7, Math.floor(720 / (symbol.modules.size + 8))));
  await QRCode.toCanvas(canvas, byteSegments(bytes), {
    errorCorrectionLevel: 'L', margin: 4, scale,
    color: { dark: '#000000ff', light: '#ffffffff' },
  });
  // The encoder writes fixed inline dimensions. Let responsive CSS size both
  // axes from the square bitmap instead of shrinking only its displayed width.
  canvas.style.width = '';
  canvas.style.height = '';
}
export function decodePixels(pixels: Pick<ImageData, 'data' | 'width' | 'height'>): Uint8Array | null {
  const result = jsQR(pixels.data, pixels.width, pixels.height, { inversionAttempts: 'dontInvert' });
  if (!result || !result.binaryData || result.binaryData.length === 0 || result.binaryData.length > 2_953) return null;
  if (!Array.from(result.binaryData).every(b => Number.isInteger(b) && b >= 0 && b <= 255)) return null;
  return Uint8Array.from(result.binaryData);
}

export async function encodeEnvelope(envelope: PairingEnvelope, options: { fragmentBytes?: number } = {}): Promise<EncodedPairing> {
  validateEnvelope(envelope);
  const json = new TextEncoder().encode(JSON.stringify(envelope));
  if (json.length > MAX_JSON_BYTES) throw new ProtocolError('qrTooLarge');
  const compressed = deflateSync(json, { level: 9 });
  if (compressed.length > MAX_COMPRESSED_BYTES) throw new ProtocolError('qrTooLarge');
  const digest = await sha256(compressed);
  const frameSize = options.fragmentBytes ?? 1_200;
  if (!Number.isInteger(frameSize) || frameSize <= HEADER_BYTES || frameSize > 2_953) throw new ProtocolError('qrTooLarge');
  const payloadSize = frameSize - HEADER_BYTES;
  const count = Math.ceil(compressed.length / payloadSize);
  if (count === 0 || count > MAX_FRAMES) throw new ProtocolError('qrTooLarge');
  const session = hexToBytes(envelope.session, 16);
  const frames: Uint8Array[] = [];
  for (let index = 0; index < count; index++) {
    const payload = compressed.subarray(index * payloadSize, (index + 1) * payloadSize);
    const frame = new Uint8Array(HEADER_BYTES + payload.length);
    frame.set(MAGIC); frame[4] = QR_VERSION; frame[5] = envelope.kind === 'offer' ? 1 : 2;
    frame[6] = 1; // raw DEFLATE (RFC 1951), no zlib or gzip wrapper
    frame[7] = 0;
    frame.set(session, 8); frame.set(digest, 24);
    const view = new DataView(frame.buffer);
    view.setUint16(56, index); view.setUint16(58, count);
    view.setUint32(60, compressed.length); view.setUint32(64, json.length);
    view.setUint16(68, payload.length); view.setUint16(70, HEADER_BYTES);
    frame.set(payload, HEADER_BYTES);
    qrSymbol(frame); // Let the actual encoder verify final Byte-mode capacity.
    frames.push(frame);
  }
  return { frames, digest: bytesToHex(digest), stats: { jsonBytes: json.length, compressedBytes: compressed.length, framedBytes: compressed.length + count * HEADER_BYTES } };
}

export interface FrameHeader {
  kind: PairingKind; session: string; digest: string; index: number; count: number;
  compressedLength: number; jsonLength: number; payload: Uint8Array;
}
export function parseFrame(frame: Uint8Array): FrameHeader {
  if (frame.length < HEADER_BYTES || frame.length > 2_953 || !equal(frame.subarray(0, 4), MAGIC)) throw new ProtocolError('qrInvalid');
  if (frame[4] !== QR_VERSION || frame[6] !== 1) throw new ProtocolError('qrUnsupported');
  if ((frame[5] !== 1 && frame[5] !== 2) || frame[7] !== 0) throw new ProtocolError('qrInvalid');
  const view = new DataView(frame.buffer, frame.byteOffset, frame.byteLength);
  const index = view.getUint16(56), count = view.getUint16(58), compressedLength = view.getUint32(60), jsonLength = view.getUint32(64);
  const payloadLength = view.getUint16(68);
  if (view.getUint16(70) !== HEADER_BYTES || payloadLength === 0 || payloadLength !== frame.length - HEADER_BYTES) throw new ProtocolError('qrInvalid');
  if (count === 0 || count > MAX_FRAMES || index >= count || compressedLength === 0 || compressedLength > MAX_COMPRESSED_BYTES
    || jsonLength === 0 || jsonLength > MAX_JSON_BYTES || payloadLength > compressedLength || count > compressedLength) throw new ProtocolError('qrTooLarge');
  if ((count === 1 && payloadLength !== compressedLength) || compressedLength > count * (2_953 - HEADER_BYTES)) throw new ProtocolError('qrInvalid');
  return { kind: frame[5] === 1 ? 'offer' : 'answer', session: bytesToHex(frame.subarray(8, 24)), digest: bytesToHex(frame.subarray(24, 56)), index, count, compressedLength, jsonLength, payload: frame.subarray(HEADER_BYTES) };
}

/** Supplies an explicit output buffer so fflate 0.8.3 cannot grow the output allocation.
 * One sentinel byte detects outputs larger than the advertised bounded JSON length.
 * Stored blocks that exceed the buffer throw; Huffman outputs fill the sentinel.
 * Never use an unbounded inflateSync followed by a length check here. */
export function inflateBounded(compressed: Uint8Array, expectedLength: number): Uint8Array {
  if (compressed.length === 0 || compressed.length > MAX_COMPRESSED_BYTES || !Number.isInteger(expectedLength)
    || expectedLength < 1 || expectedLength > MAX_JSON_BYTES) throw new ProtocolError('qrTooLarge');
  try {
    const output = inflateSync(compressed, { out: new Uint8Array(expectedLength + 1) });
    if (output.length > expectedLength) throw new ProtocolError('qrTooLarge');
    if (output.length !== expectedLength) throw new ProtocolError('qrInvalid');
    return output;
  } catch (error) {
    if (error instanceof ProtocolError) throw error;
    if (error instanceof RangeError) throw new ProtocolError('qrTooLarge');
    throw new ProtocolError('qrInvalid');
  }
}

export interface CollectedFrame { collected: number; total: number; complete: boolean; envelope?: PairingEnvelope; digest?: string }
export class FrameCollector {
  private header: FrameHeader | null = null;
  private readonly parts = new Map<number, Uint8Array>();
  private bytes = 0;
  private started = performance.now();
  constructor(private readonly expected: { kind?: PairingKind; session?: string } = {}) {}
  clear(): void { this.header = null; this.parts.clear(); this.bytes = 0; this.started = performance.now(); }
  async push(frame: Uint8Array): Promise<CollectedFrame> {
    if (performance.now() - this.started > PENDING_MS) { this.clear(); throw new ProtocolError('qrExpired'); }
    const next = parseFrame(frame);
    if ((this.expected.kind && next.kind !== this.expected.kind) || (this.expected.session && next.session !== this.expected.session)) throw new ProtocolError('qrWrongSession');
    if (this.header) {
      const first = this.header;
      if (first.session !== next.session || first.kind !== next.kind) throw new ProtocolError('qrWrongSession');
      if (first.digest !== next.digest || first.count !== next.count || first.compressedLength !== next.compressedLength || first.jsonLength !== next.jsonLength) throw new ProtocolError('qrConflict');
    }
    const existing = this.parts.get(next.index);
    if (existing && !equal(existing, next.payload)) throw new ProtocolError('qrConflict');
    if (!existing) {
      if (this.bytes + next.payload.length > next.compressedLength) throw new ProtocolError('qrInvalid');
      this.header ??= { ...next, payload: new Uint8Array(0) };
      this.parts.set(next.index, Uint8Array.from(next.payload)); this.bytes += next.payload.length;
    }
    const progress = { collected: this.parts.size, total: next.count, complete: false };
    if (this.parts.size !== next.count) return progress;
    if (this.bytes !== next.compressedLength) throw new ProtocolError('qrInvalid');
    const compressed = new Uint8Array(next.compressedLength);
    let offset = 0;
    for (let i = 0; i < next.count; i++) {
      const part = this.parts.get(i);
      if (!part) throw new ProtocolError('qrInvalid');
      compressed.set(part, offset); offset += part.length;
    }
    if (bytesToHex(await sha256(compressed)) !== next.digest) throw new ProtocolError('qrIntegrity');
    const json = inflateBounded(compressed, next.jsonLength);
    let value: unknown;
    try { value = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(json)); }
    catch { throw new ProtocolError('qrInvalid'); }
    const envelope = validateEnvelope(value);
    if (envelope.kind !== next.kind || envelope.session !== next.session) throw new ProtocolError('qrWrongSession');
    return { ...progress, complete: true, envelope, digest: next.digest };
  }
}
