import {
  FrameCollector, PENDING_MS, ProtocolError, encodeEnvelope, randomId,
  type PairingEnvelope, type PairingStats,
} from './qr';
import type { Transport } from './transport';

export type SessionState = 'idle' | 'preparing-offer' | 'displaying-offer' | 'scanning-offer'
  | 'preparing-answer' | 'displaying-answer' | 'scanning-answer' | 'connecting' | 'connected'
  | 'expired' | 'failed' | 'disconnected';
const CONTROL_HEADER = 20;
const MAX_CONTROL = 524_288;
const MAX_CONTROL_QUEUE = 1_048_576;
const CONTROL_MAGIC = 0x514c4331; // QLC1
const DATA_MESSAGE_BYTES = 16_384;
const GATHER_MS = 20_000;
const CONNECT_MS = 90_000;
type IncomingControl = { count: number; total: number; bytes: number; parts: Map<number, Uint8Array>; timer: ReturnType<typeof setTimeout> };

function object(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/** Data-only native connection, retained throughout QR display and optional media calls. */
export class Session implements Transport {
  sessionId = '';
  isCreator = false;
  state: SessionState = 'idle';
  error: string | null = null;
  frames: Uint8Array[] = [];
  stats: PairingStats = { jsonBytes: 0, compressedBytes: 0, framedBytes: 0 };
  pc: RTCPeerConnection | null = null;
  onChange: (() => void) | null = null;
  private control: RTCDataChannel | null = null;
  private files: RTCDataChannel | null = null;
  private collector: FrameCollector | null = null;
  private outgoing: PairingEnvelope | null = null;
  private offerDigest = '';
  private deadline = 0;
  private generation = 0;
  private gatheringAbort: AbortController | null = null;
  private notifiedClose = true;
  private helloReceived = false;
  private expiryTimer: ReturnType<typeof setTimeout> | undefined;
  private connectTimer: ReturnType<typeof setTimeout> | undefined;
  private disconnectedTimer: ReturnType<typeof setTimeout> | undefined;
  private readonly messages = new Set<(message: Record<string, unknown>) => void>();
  private readonly binaries = new Set<(data: ArrayBuffer) => void>();
  private readonly closers = new Set<() => void>();
  private readonly incomingControl = new Map<number, IncomingControl>();
  private nextMessage = 0;
  private sendChain: Promise<void> = Promise.resolve();
  private binaryChain: Promise<void> = Promise.resolve();
  private queuedControl = 0;

  get connected(): boolean { return this.state === 'connected' && this.control?.readyState === 'open'; }
  get diagnostics(): Record<string, string | number> {
    return {
      protocol: 1, state: this.state,
      gathering: this.pc?.iceGatheringState ?? 'new', ice: this.pc?.iceConnectionState ?? 'new',
      connection: this.pc?.connectionState ?? 'new', control: this.control?.readyState ?? 'closed',
      files: this.files?.readyState ?? 'closed', frames: this.frames.length, maxMessageSize: this.maxMessageSize,
      ...this.stats,
    };
  }
  get maxMessageSize(): number {
    const negotiated = this.pc?.sctp?.maxMessageSize;
    return !negotiated || !Number.isFinite(negotiated) ? DATA_MESSAGE_BYTES : Math.min(DATA_MESSAGE_BYTES, negotiated);
  }
  onMessage(listener: (message: Record<string, unknown>) => void): () => void { this.messages.add(listener); return () => this.messages.delete(listener); }
  onBinary(listener: (data: ArrayBuffer) => void): () => void { this.binaries.add(listener); return () => this.binaries.delete(listener); }
  onClose(listener: () => void): () => void { this.closers.add(listener); return () => this.closers.delete(listener); }
  private changed(): void { this.onChange?.(); }
  private setState(state: SessionState): void { this.state = state; this.changed(); }
  private checkGeneration(generation: number): void {
    if (generation !== this.generation) throw new ProtocolError('sessionClosed');
  }
  private requireBrowser(): void {
    if (!globalThis.isSecureContext) throw new ProtocolError('insecure');
    if (!globalThis.RTCPeerConnection || !globalThis.crypto?.subtle) throw new ProtocolError('unsupported');
  }

  async create(easy = false): Promise<void> {
    this.reset();
    const generation = this.generation;
    try {
      this.requireBrowser();
      this.sessionId = randomId(); this.isCreator = true;
      this.startExpiry(PENDING_MS);
      this.setState('preparing-offer');
      const pc = this.makePeer();
      this.attachChannel(pc.createDataChannel('control', { ordered: true, protocol: 'qrlink/1' }));
      await pc.setLocalDescription(await pc.createOffer());
      await waitForGathering(pc, GATHER_MS, this.gatheringAbort?.signal);
      this.checkGeneration(generation);
      const description = finalDescription(pc, 'offer');
      const created = Date.now();
      const remaining = Math.max(1, this.deadline - performance.now());
      this.outgoing = { v: 1, kind: 'offer', session: this.sessionId, created, expires: created + Math.floor(remaining), description };
      await this.applyEncoding(easy);
      this.checkGeneration(generation);
      this.setState('displaying-offer');
    } catch (error) { if (generation === this.generation) this.fail(error); throw error; }
  }

  join(): void {
    this.reset();
    try { this.requireBrowser(); this.collector = new FrameCollector({ kind: 'offer' }); this.setState('scanning-offer'); }
    catch (error) { this.fail(error); }
  }
  scanAnswer(): void {
    if (!this.isCreator || !this.pc || !this.outgoing || (this.state !== 'displaying-offer' && this.state !== 'scanning-answer')) return;
    if (!this.pending()) return;
    this.error = null;
    this.collector = new FrameCollector({ kind: 'answer', session: this.sessionId });
    this.setState('scanning-answer');
  }
  async reframe(easy: boolean): Promise<void> {
    if (!this.outgoing || !this.pending()) return;
    const generation = this.generation;
    try { await this.applyEncoding(easy); this.checkGeneration(generation); this.changed(); }
    catch (error) { if (generation === this.generation) { this.error = errorKey(error); this.changed(); } throw error; }
  }
  private async applyEncoding(easy: boolean): Promise<void> {
    const generation = this.generation;
    const outgoing = this.outgoing;
    if (!outgoing) throw new ProtocolError('sessionClosed');
    const encoded = await encodeEnvelope(outgoing, { fragmentBytes: easy ? 450 : 1_200 });
    this.checkGeneration(generation);
    this.frames = encoded.frames; this.stats = encoded.stats;
    if (outgoing.kind === 'offer') this.offerDigest = encoded.digest;
  }
  async receiveFrame(bytes: Uint8Array): Promise<{ collected: number; total: number; complete: boolean }> {
    if (!this.collector || (this.state !== 'scanning-offer' && this.state !== 'scanning-answer')) throw new ProtocolError('qrWrongSession');
    if (this.isCreator && !this.pending()) throw new ProtocolError('qrExpired');
    const generation = this.generation;
    let result;
    try { result = await this.collector.push(bytes); }
    catch (error) { this.error = errorKey(error); this.changed(); throw error; }
    this.checkGeneration(generation);
    if (!result.complete || !result.envelope) return result;
    const envelope = result.envelope;
    try {
      if (this.isCreator) {
        if (!this.pending()) throw new ProtocolError('qrExpired');
        if (envelope.kind !== 'answer' || envelope.session !== this.sessionId || envelope.offerDigest !== this.offerDigest) throw new ProtocolError('qrWrongSession');
        if (!this.pc || !this.outgoing || envelope.expires !== this.outgoing.expires) throw new ProtocolError('qrWrongSession');
        await this.pc.setRemoteDescription(envelope.description);
        this.checkGeneration(generation);
        this.collector?.clear(); this.collector = null; this.error = null;
        if (!this.connected) this.setState('connecting');
        this.startConnectTimeout();
      } else {
        if (envelope.kind !== 'offer' || !result.digest) throw new ProtocolError('qrWrongSession');
        this.sessionId = envelope.session; this.offerDigest = result.digest;
        this.startExpiry(Math.min(PENDING_MS, envelope.expires - Date.now()));
        this.setState('preparing-answer');
        const pc = this.makePeer();
        await pc.setRemoteDescription(envelope.description);
        await pc.setLocalDescription(await pc.createAnswer());
        await waitForGathering(pc, GATHER_MS, this.gatheringAbort?.signal);
        this.checkGeneration(generation);
        this.outgoing = { v: 1, kind: 'answer', session: envelope.session, created: Date.now(), expires: envelope.expires,
          offerDigest: result.digest, description: finalDescription(pc, 'answer') };
        await this.applyEncoding(false);
        this.checkGeneration(generation);
        this.collector?.clear(); this.collector = null; this.error = null;
        if (!this.connected) this.setState('displaying-answer');
        this.startConnectTimeout();
      }
      return { collected: result.collected, total: result.total, complete: true };
    } catch (error) { if (generation === this.generation) this.fail(error); throw error; }
  }

  private makePeer(): RTCPeerConnection {
    const pc = new RTCPeerConnection({ iceServers: [], bundlePolicy: 'max-bundle' });
    this.gatheringAbort = new AbortController();
    this.pc = pc; this.notifiedClose = false;
    const generation = this.generation;
    // Register before setRemoteDescription/createOffer, which may cause channel events.
    pc.addEventListener('datachannel', event => {
      if (generation !== this.generation) { event.channel.close(); return; }
      try { this.attachChannel(event.channel); } catch (error) { this.fail(error); }
    });
    pc.addEventListener('connectionstatechange', () => {
      if (generation !== this.generation) return;
      if (pc.connectionState === 'failed') {
        if (this.helloReceived) this.end('disconnected', 'connectionFailed');
        else this.fail(new ProtocolError('connectionFailed'));
      }
      else if (pc.connectionState === 'closed') this.end('disconnected', 'peerClosed');
      else if (pc.connectionState === 'disconnected') {
        this.disconnectedTimer ??= setTimeout(() => {
          if (generation === this.generation && pc.connectionState === 'disconnected') this.end('disconnected', 'connectionFailed');
        }, 10_000);
      } else { clearTimeout(this.disconnectedTimer); this.disconnectedTimer = undefined; }
      this.changed();
    });
    return pc;
  }
  private attachChannel(channel: RTCDataChannel): void {
    if (!channel.ordered || channel.maxRetransmits !== null || channel.maxPacketLifeTime !== null) throw new ProtocolError('protocolError');
    if (channel.label === 'control' && !this.control) this.control = channel;
    else if (channel.label === 'files' && !this.files) this.files = channel;
    else { channel.close(); throw new ProtocolError('protocolError'); }
    channel.binaryType = 'arraybuffer';
    channel.bufferedAmountLowThreshold = channel.label === 'control' ? 65_536 : 131_072;
    const generation = this.generation;
    channel.addEventListener('open', () => {
      if (generation !== this.generation) return;
      if (channel.label === 'control') {
        if (this.isCreator && !this.files) {
          this.attachChannel(this.pc!.createDataChannel('files', { ordered: true, protocol: 'qrlink-files/1' }));
        }
        void this.sendControl({ _ql: 'hello', v: 1, session: this.sessionId, capabilities: ['files-v1', 'calls-v1'] })
          .catch(error => { if (generation === this.generation) this.fail(error); });
      }
      this.changed();
    });
    channel.addEventListener('message', event => {
      if (generation !== this.generation) return;
      try {
        if (!(event.data instanceof ArrayBuffer) || event.data.byteLength > this.maxMessageSize) throw new ProtocolError('protocolError');
        if (channel.label === 'control') this.receiveControl(event.data);
        else {
          if (!this.helloReceived) throw new ProtocolError('protocolError');
          this.binaries.forEach(listener => listener(event.data as ArrayBuffer));
        }
      } catch (error) { this.fail(error); }
    });
    channel.addEventListener('close', () => { if (generation === this.generation) this.end('disconnected', 'peerClosed'); });
    channel.addEventListener('error', () => {
      if (generation !== this.generation) return;
      // Some engines report an SCTP abort before close when the other tab leaves.
      // An established session has disconnected; it did not fail QR pairing.
      if (this.helloReceived) this.end('disconnected', 'peerClosed');
      else this.fail(new ProtocolError('connectionFailed'));
    });
  }

  async send(message: Record<string, unknown>): Promise<void> {
    if (!this.connected || '_ql' in message) throw new ProtocolError('sessionClosed');
    return this.sendControl(message);
  }
  private sendControl(message: Record<string, unknown>): Promise<void> {
    let bytes: Uint8Array;
    try { bytes = new TextEncoder().encode(JSON.stringify(message)); }
    catch { return Promise.reject(new ProtocolError('protocolError')); }
    if (bytes.length === 0 || bytes.length > MAX_CONTROL || this.queuedControl + bytes.length > MAX_CONTROL_QUEUE) return Promise.reject(new ProtocolError('protocolError'));
    this.queuedControl += bytes.length;
    const generation = this.generation;
    const job = this.sendChain.catch(() => undefined).then(async () => {
      this.checkGeneration(generation);
      const channel = this.control;
      if (!channel || channel.readyState !== 'open') throw new ProtocolError('sessionClosed');
      const payloadSize = this.maxMessageSize - CONTROL_HEADER;
      if (payloadSize < 64) throw new ProtocolError('protocolError');
      const count = Math.ceil(bytes.length / payloadSize), id = this.nextMessage++ >>> 0;
      if (count > 1_024) throw new ProtocolError('protocolError');
      for (let index = 0; index < count; index++) {
        await backpressure(channel, 262_144);
        this.checkGeneration(generation);
        const payload = bytes.subarray(index * payloadSize, (index + 1) * payloadSize);
        const frame = new Uint8Array(CONTROL_HEADER + payload.length), view = new DataView(frame.buffer);
        view.setUint32(0, CONTROL_MAGIC); view.setUint32(4, id);
        view.setUint16(8, index); view.setUint16(10, count);
        view.setUint32(12, bytes.length); view.setUint32(16, payload.length);
        frame.set(payload, CONTROL_HEADER); channel.send(frame.buffer);
      }
    }).finally(() => { if (generation === this.generation) this.queuedControl -= bytes.length; });
    this.sendChain = job;
    return job;
  }
  private receiveControl(data: ArrayBuffer): void {
    if (data.byteLength < CONTROL_HEADER) throw new ProtocolError('protocolError');
    const view = new DataView(data);
    const id = view.getUint32(4), index = view.getUint16(8), count = view.getUint16(10), total = view.getUint32(12), length = view.getUint32(16);
    if (view.getUint32(0) !== CONTROL_MAGIC || count === 0 || count > 1_024 || index >= count || total === 0 || total > MAX_CONTROL
      || length === 0 || length !== data.byteLength - CONTROL_HEADER || length > total || count > total) throw new ProtocolError('protocolError');
    let incoming = this.incomingControl.get(id);
    if (!incoming) {
      // Reliable ordered channel: the first fragment must have index zero.
      if (index !== 0 || this.incomingControl.size >= 2) throw new ProtocolError('protocolError');
      const timer = setTimeout(() => { this.incomingControl.delete(id); this.fail(new ProtocolError('protocolError')); }, 15_000);
      incoming = { count, total, bytes: 0, parts: new Map(), timer }; this.incomingControl.set(id, incoming);
    }
    if (incoming.count !== count || incoming.total !== total || index !== incoming.parts.size || incoming.bytes + length > total) throw new ProtocolError('protocolError');
    incoming.parts.set(index, new Uint8Array(data, CONTROL_HEADER).slice()); incoming.bytes += length;
    if (incoming.parts.size !== count) return;
    if (incoming.bytes !== total) throw new ProtocolError('protocolError');
    const joined = new Uint8Array(total); let offset = 0;
    for (const part of incoming.parts.values()) { joined.set(part, offset); offset += part.length; }
    clearTimeout(incoming.timer); this.incomingControl.delete(id);
    let message: unknown;
    try { message = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(joined)); }
    catch { throw new ProtocolError('protocolError'); }
    if (!object(message)) throw new ProtocolError('protocolError');
    if ('_ql' in message) {
      if (message._ql !== 'hello' || this.helloReceived || message.v !== 1 || message.session !== this.sessionId
        || !Array.isArray(message.capabilities) || message.capabilities.length > 16
        || !message.capabilities.includes('files-v1') || !message.capabilities.includes('calls-v1')) throw new ProtocolError('protocolError');
      if (!this.pending()) throw new ProtocolError('qrExpired');
      this.helloReceived = true; clearTimeout(this.expiryTimer); clearTimeout(this.connectTimer);
      this.expiryTimer = undefined; this.connectTimer = undefined;
      this.collector?.clear(); this.collector = null; this.outgoing = null; this.frames = []; this.offerDigest = '';
      this.error = null; this.setState('connected');
    } else {
      if (!this.helloReceived) throw new ProtocolError('protocolError');
      this.messages.forEach(listener => listener(message));
    }
  }
  sendBinary(data: ArrayBuffer): Promise<void> {
    if (!this.connected || data.byteLength === 0 || data.byteLength > this.maxMessageSize) return Promise.reject(new ProtocolError('sessionClosed'));
    const generation = this.generation;
    const job = this.binaryChain.catch(() => undefined).then(async () => {
      this.checkGeneration(generation);
      const channel = this.files;
      if (!channel) throw new ProtocolError('sessionClosed');
      await channelOpen(channel);
      await backpressure(channel, 524_288);
      this.checkGeneration(generation); channel.send(data);
    });
    this.binaryChain = job;
    return job;
  }

  private startExpiry(duration: number): void {
    this.deadline = performance.now() + Math.max(0, duration);
    clearTimeout(this.expiryTimer);
    this.expiryTimer = setTimeout(() => this.end('expired', 'qrExpired'), Math.max(0, duration));
  }
  private pending(): boolean {
    if (performance.now() < this.deadline) return true;
    this.end('expired', 'qrExpired'); return false;
  }
  private startConnectTimeout(): void {
    if (this.connected) return;
    clearTimeout(this.connectTimer);
    this.connectTimer = setTimeout(() => this.fail(new ProtocolError('connectionTimeout')), CONNECT_MS);
  }
  private fail(error: unknown): void {
    const key = errorKey(error);
    this.end(key === 'qrExpired' ? 'expired' : 'failed', key);
  }
  private reset(): void {
    this.cleanup(); this.isCreator = false; this.sessionId = ''; this.error = null;
    this.stats = { jsonBytes: 0, compressedBytes: 0, framedBytes: 0 }; this.state = 'idle';
  }
  private end(state: SessionState, error: string | null): void {
    this.cleanup(); this.error = error; this.setState(state);
  }
  disconnect(): void { this.end('disconnected', null); }
  private cleanup(): void {
    this.generation++;
    this.gatheringAbort?.abort(); this.gatheringAbort = null;
    clearTimeout(this.expiryTimer); clearTimeout(this.connectTimer); clearTimeout(this.disconnectedTimer);
    this.expiryTimer = undefined; this.connectTimer = undefined; this.disconnectedTimer = undefined;
    this.incomingControl.forEach(value => clearTimeout(value.timer)); this.incomingControl.clear();
    this.collector?.clear(); this.collector = null; this.frames = []; this.outgoing = null; this.offerDigest = '';
    this.helloReceived = false; this.deadline = 0;
    const pc = this.pc; this.pc = null;
    const control = this.control, files = this.files; this.control = null; this.files = null;
    control?.close(); files?.close(); pc?.close();
    this.sendChain = Promise.resolve(); this.binaryChain = Promise.resolve(); this.queuedControl = 0;
    if (!this.notifiedClose) { this.notifiedClose = true; this.closers.forEach(listener => listener()); }
  }
}

export function errorKey(error: unknown): string { return error instanceof ProtocolError ? error.key : 'connectionFailed'; }
function finalDescription(pc: RTCPeerConnection, kind: 'offer' | 'answer'): { type: 'offer' | 'answer'; sdp: string } {
  const description = pc.localDescription;
  if (!description || description.type !== kind || !description.sdp) throw new ProtocolError('connectionFailed');
  if (!/^a=candidate:/m.test(description.sdp)) throw new ProtocolError('noCandidates');
  return { type: kind, sdp: description.sdp };
}
export function waitForGathering(pc: RTCPeerConnection, timeout = GATHER_MS, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    let settled = false;
    const finish = (error?: ProtocolError): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timer); pc.removeEventListener('icegatheringstatechange', check); pc.removeEventListener('connectionstatechange', check);
      signal?.removeEventListener('abort', abort);
      if (error) reject(error); else resolve();
    };
    const check = (): void => {
      if (pc.connectionState === 'closed') finish(new ProtocolError('sessionClosed'));
      else if (pc.iceGatheringState === 'complete') finish();
    };
    const abort = (): void => finish(new ProtocolError('sessionClosed'));
    const timer = setTimeout(() => finish(new ProtocolError('iceTimeout')), timeout);
    pc.addEventListener('icegatheringstatechange', check); pc.addEventListener('connectionstatechange', check);
    signal?.addEventListener('abort', abort, { once: true });
    if (signal?.aborted) abort();
    else check(); // Covers gathering that finished before the listeners were installed.
  });
}
async function channelOpen(channel: RTCDataChannel): Promise<void> {
  if (channel.readyState === 'open') return;
  if (channel.readyState !== 'connecting') throw new ProtocolError('sessionClosed');
  await new Promise<void>((resolve, reject) => {
    const finish = (error?: ProtocolError): void => {
      clearTimeout(timer); channel.removeEventListener('open', open); channel.removeEventListener('close', close);
      if (error) reject(error); else resolve();
    };
    const open = (): void => finish(), close = (): void => finish(new ProtocolError('sessionClosed'));
    const timer = setTimeout(() => finish(new ProtocolError('connectionTimeout')), 10_000);
    channel.addEventListener('open', open); channel.addEventListener('close', close);
    if (channel.readyState === 'open') finish();
  });
}
async function backpressure(channel: RTCDataChannel, highWater: number): Promise<void> {
  if (channel.readyState !== 'open') throw new ProtocolError('sessionClosed');
  if (channel.bufferedAmount <= highWater) return;
  await new Promise<void>((resolve, reject) => {
    const finish = (error?: ProtocolError): void => {
      clearTimeout(timer); channel.removeEventListener('bufferedamountlow', low); channel.removeEventListener('close', closed);
      if (error) reject(error); else resolve();
    };
    const low = (): void => { if (channel.bufferedAmount <= channel.bufferedAmountLowThreshold) finish(); };
    const closed = (): void => finish(new ProtocolError('sessionClosed'));
    const timer = setTimeout(() => finish(new ProtocolError('connectionTimeout')), 20_000);
    channel.addEventListener('bufferedamountlow', low); channel.addEventListener('close', closed); low();
  });
}
