import type { Transport } from './transport';

export type TransferState = 'offered' | 'sending' | 'receiving' | 'verifying' | 'complete' | 'rejected' | 'cancelled' | 'failed';
export type FileError = 'fileTooLarge' | 'fileBusy' | 'fileRejected' | 'fileCancelled' | 'fileInterrupted' | 'fileIntegrity' | 'fileInvalid' | 'fileUnavailable' | 'fileTimeout';
export interface TransferView {
  id: string;
  name: string;
  size: number;
  received: number;
  direction: 'send' | 'receive';
  state: TransferState;
  url?: string;
  error?: FileError;
  /** Bytes per second, averaged over the current transfer. */
  speed: number;
}

export const MAX_FILE_SIZE = 100 * 1024 * 1024;
export const FILE_MEMORY_BUDGET = 384 * 1024 * 1024;
export const FILE_FRAME_SIZE = 16 * 1024;
const HEADER_SIZE = 28;
const MAGIC = [0x51, 0x4c, 0x46, 0x31]; // QLF1
const HISTORY_LIMIT = 24;
const OFFER_TIMEOUT = 5 * 60_000;
const IDLE_TIMEOUT = 60_000;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const DIGEST = /^[0-9a-f]{64}$/;
const ERRORS = new Set<FileError>(['fileTooLarge', 'fileBusy', 'fileRejected', 'fileCancelled', 'fileInterrupted', 'fileIntegrity', 'fileInvalid', 'fileUnavailable', 'fileTimeout']);
const TERMINAL = new Set<TransferState>(['complete', 'rejected', 'cancelled', 'failed']);

interface RecordEntry {
  view: TransferView;
  file?: File;
  buffer?: Uint8Array<ArrayBuffer>;
  digest: string;
  endReceived: boolean;
  memory: number;
  started: number;
  progressSent: number;
  timer?: ReturnType<typeof setTimeout>;
  paceTimer?: ReturnType<typeof setTimeout>;
  resume?: () => void;
}
interface Capabilities { maxFileSize: number; availableBytes: number; chunkSize: number }

/** Strip path separators, control/bidi characters and platform-reserved names. */
export function sanitizeFilename(name: string): string {
  let safe = name.normalize('NFC').replace(/[\u0000-\u001f\u007f-\u009f\u202a-\u202e\u2066-\u2069/\\:*?"<>|]/g, '_').trim().replace(/[. ]+$/g, '');
  safe = Array.from(safe).slice(0, 200).join('');
  if (!safe || /^\.+$/.test(safe)) safe = 'download';
  if (/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(safe)) safe = `_${safe}`;
  return safe;
}

function isInteger(value: unknown, max: number): value is number { return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value <= max; }
function idValid(value: unknown): value is string { return typeof value === 'string' && UUID.test(value); }
function errorValid(value: unknown): value is FileError { return typeof value === 'string' && ERRORS.has(value as FileError); }
function asError(key: FileError): Error { return new Error(key); }
function bytesForId(id: string): Uint8Array<ArrayBuffer> {
  return Uint8Array.from(id.replace(/-/g, '').match(/../g)!, (byte) => Number.parseInt(byte, 16));
}
function idForBytes(bytes: Uint8Array): string {
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
async function digestOf(buffer: ArrayBuffer): Promise<string> {
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', buffer)), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

/** One active file in each direction; all content stays in volatile browser memory. */
export class FileController {
  transfers: TransferView[] = [];
  onChange: (() => void) | null = null;
  callActive = false;
  private readonly records = new Map<string, RecordEntry>();
  private readonly unsubscribe: (() => void)[];
  private remote?: Capabilities;
  private reservedMemory = 0;
  private senderHashMemory = 0;
  private offering = false;
  private disposed = false;
  private offerTimes: number[] = [];

  constructor(private readonly transport: Transport) {
    this.unsubscribe = [transport.onMessage((message) => { void this.receiveControl(message).catch(() => { /* Invalid input never escapes the channel listener. */ }); }), transport.onBinary((data) => this.receiveBinary(data)), transport.onClose(() => this.interrupt())];
    this.advertise(false);
  }

  private emit(): void { if (!this.disposed) this.onChange?.(); }
  private send(action: string, fields: Record<string, unknown> = {}): Promise<void> {
    if (this.disposed || !this.transport.connected) return Promise.reject(asError('fileInterrupted'));
    return this.transport.send({ type: 'file', v: 1, sessionId: this.transport.sessionId, action, ...fields });
  }
  private notify(action: string, fields: Record<string, unknown> = {}): void { void this.send(action, fields).catch(() => { /* Connection lifecycle reports interruption. */ }); }
  private advertise(response: boolean): void {
    this.notify('capabilities', { maxFileSize: MAX_FILE_SIZE, memoryBudget: FILE_MEMORY_BUDGET, availableBytes: Math.max(0, Math.floor((FILE_MEMORY_BUDGET - this.reservedMemory - this.senderHashMemory) / 3)), chunkSize: FILE_FRAME_SIZE, response });
  }
  private active(direction: TransferView['direction']): boolean {
    return [...this.records.values()].some((record) => record.view.direction === direction && !TERMINAL.has(record.view.state));
  }
  private add(view: TransferView, digest: string): RecordEntry {
    const record: RecordEntry = { view, digest, endReceived: false, memory: 0, started: 0, progressSent: 0 };
    this.records.set(view.id, record);
    this.transfers.push(view);
    while (this.transfers.length > HISTORY_LIMIT) {
      const index = this.transfers.findIndex((entry) => TERMINAL.has(entry.state));
      if (index < 0) break;
      this.discard(this.transfers[index]!.id);
    }
    this.arm(record, OFFER_TIMEOUT);
    this.emit();
    return record;
  }
  private arm(record: RecordEntry, delay = IDLE_TIMEOUT): void {
    clearTimeout(record.timer);
    record.timer = setTimeout(() => { this.fail(record, 'fileTimeout'); this.notify('cancel', { id: record.view.id }); }, delay);
  }
  private release(record: RecordEntry, retainBlob = false): void {
    clearTimeout(record.timer);
    record.timer = undefined;
    clearTimeout(record.paceTimer);
    record.resume?.();
    record.resume = undefined;
    record.buffer = undefined;
    record.file = undefined;
    const remaining = retainBlob ? record.view.size : 0;
    this.reservedMemory -= record.memory - remaining;
    record.memory = remaining;
    this.advertise(true);
  }
  private fail(record: RecordEntry, error: FileError, state: TransferState = 'failed'): void {
    if (TERMINAL.has(record.view.state)) return;
    record.view.state = state;
    record.view.error = error;
    this.release(record);
    this.emit();
  }

  async offer(file: File): Promise<void> {
    if (this.disposed || !this.transport.connected || !this.remote) throw asError('fileUnavailable');
    if (this.offering || this.active('send')) throw asError('fileBusy');
    if (!isInteger(file.size, Math.min(MAX_FILE_SIZE, this.remote.maxFileSize, this.remote.availableBytes))) throw asError('fileTooLarge');
    // Web Crypto's digest API is not streaming: bound its input and its working copy.
    if (this.reservedMemory + file.size * 2 > FILE_MEMORY_BUDGET) throw asError('fileBusy');
    this.offering = true;
    this.senderHashMemory = file.size * 2;
    this.advertise(true);
    try {
      const digest = await digestOf(await file.arrayBuffer());
      if (this.disposed || !this.transport.connected) throw asError('fileInterrupted');
      const id = crypto.randomUUID();
      const view: TransferView = { id, name: sanitizeFilename(file.name), size: file.size, received: 0, direction: 'send', state: 'offered', speed: 0 };
      const record = this.add(view, digest);
      record.file = file;
      try { await this.send('offer', { id, name: view.name, size: file.size, mime: file.type.slice(0, 127), sha256: digest }); }
      catch { this.fail(record, 'fileInterrupted'); throw asError('fileInterrupted'); }
    } finally {
      this.offering = false;
      this.senderHashMemory = 0;
      this.advertise(true);
    }
  }

  async accept(id: string): Promise<void> {
    const record = this.records.get(id);
    if (!record || record.view.direction !== 'receive' || record.view.state !== 'offered') return;
    const memory = record.view.size * 3;
    if (memory + this.reservedMemory + this.senderHashMemory > FILE_MEMORY_BUDGET) {
      this.notify('reject', { id, reason: 'fileBusy' });
      this.fail(record, 'fileBusy', 'rejected');
      return;
    }
    try { record.buffer = new Uint8Array(record.view.size); }
    catch { this.notify('reject', { id, reason: 'fileBusy' }); this.fail(record, 'fileBusy', 'rejected'); return; }
    record.memory = memory;
    this.reservedMemory += memory;
    record.started = performance.now();
    record.view.state = 'receiving';
    this.arm(record);
    this.advertise(true);
    this.emit();
    try { await this.send('accept', { id }); }
    catch { this.fail(record, 'fileInterrupted'); }
  }

  reject(id: string): void {
    const record = this.records.get(id);
    if (!record || record.view.direction !== 'receive' || record.view.state !== 'offered') return;
    this.notify('reject', { id, reason: 'fileRejected' });
    this.fail(record, 'fileRejected', 'rejected');
  }
  cancel(id: string): void {
    const record = this.records.get(id);
    if (!record || TERMINAL.has(record.view.state)) return;
    this.notify('cancel', { id });
    this.fail(record, 'fileCancelled', 'cancelled');
  }
  /** Release a completed download early, or remove a terminal history entry. */
  discard(id: string): void {
    const record = this.records.get(id);
    if (!record || !TERMINAL.has(record.view.state)) return;
    if (record.view.url) URL.revokeObjectURL(record.view.url);
    this.reservedMemory -= record.memory;
    record.memory = 0;
    this.records.delete(id);
    this.transfers = this.transfers.filter((view) => view.id !== id);
    this.advertise(true);
    this.emit();
  }

  private async receiveControl(message: Record<string, unknown>): Promise<void> {
    if (this.disposed || message.type !== 'file' || message.v !== 1 || message.sessionId !== this.transport.sessionId) return;
    const action = message.action;
    if (action === 'capabilities') {
      if (!isInteger(message.maxFileSize, 1024 * 1024 * 1024) || !isInteger(message.availableBytes, 1024 * 1024 * 1024) || !isInteger(message.chunkSize, FILE_FRAME_SIZE) || message.chunkSize <= HEADER_SIZE) return;
      this.remote = { maxFileSize: message.maxFileSize, availableBytes: message.availableBytes, chunkSize: message.chunkSize };
      if (message.response !== true) this.advertise(true);
      this.emit();
      return;
    }
    if (!idValid(message.id)) return;
    const id = message.id.toLowerCase();
    if (action === 'offer') {
      if (this.records.has(id)) return;
      const now = performance.now();
      this.offerTimes = this.offerTimes.filter((time) => now - time < 60_000);
      if (this.offerTimes.length >= 32) return;
      this.offerTimes.push(now);
      if (typeof message.name !== 'string' || message.name.length === 0 || message.name.length > 1024 || typeof message.sha256 !== 'string' || !DIGEST.test(message.sha256) || (message.mime !== undefined && (typeof message.mime !== 'string' || message.mime.length > 127))) {
        this.notify('reject', { id, reason: 'fileInvalid' }); return;
      }
      if (!isInteger(message.size, MAX_FILE_SIZE)) { this.notify('reject', { id, reason: 'fileTooLarge' }); return; }
      if (this.active('receive') || message.size * 3 + this.reservedMemory + this.senderHashMemory > FILE_MEMORY_BUDGET) { this.notify('reject', { id, reason: 'fileBusy' }); return; }
      this.add({ id, name: sanitizeFilename(message.name), size: message.size, received: 0, direction: 'receive', state: 'offered', speed: 0 }, message.sha256);
      return;
    }
    const record = this.records.get(id);
    if (!record || TERMINAL.has(record.view.state)) return;
    if (action === 'cancel') { this.fail(record, 'fileCancelled', 'cancelled'); return; }
    if (action === 'error') { this.fail(record, errorValid(message.reason) ? message.reason : 'fileInvalid'); return; }
    if (record.view.direction === 'send') {
      if (action === 'reject' && record.view.state === 'offered') this.fail(record, errorValid(message.reason) ? message.reason : 'fileRejected', 'rejected');
      else if (action === 'accept' && record.view.state === 'offered') {
        record.view.state = 'sending';
        record.started = performance.now();
        this.arm(record);
        this.emit();
        void this.sendFile(record);
      } else if (action === 'progress' && (record.view.state === 'sending' || record.view.state === 'verifying')) {
        if (!isInteger(message.received, record.view.size)) { this.protocolError(record); return; }
        this.arm(record);
      } else if (action === 'ack' && record.view.state === 'verifying') {
        if (message.sha256 !== record.digest) { this.protocolError(record); return; }
        record.view.state = 'complete';
        this.release(record);
        this.emit();
      }
    } else if (action === 'end' && record.view.state === 'receiving') {
      if (message.size !== record.view.size || message.sha256 !== record.digest || record.endReceived) { this.protocolError(record); return; }
      record.endReceived = true;
      this.arm(record);
      await this.maybeComplete(record);
    }
  }

  private protocolError(record: RecordEntry, error: FileError = 'fileInvalid'): void {
    this.notify('error', { id: record.view.id, reason: error });
    this.fail(record, error);
  }
  private async sendFile(record: RecordEntry): Promise<void> {
    try {
      const file = record.file;
      if (!file) throw asError('fileInvalid');
      const negotiated = this.transport.maxMessageSize;
      const maximum = Math.min(FILE_FRAME_SIZE, this.remote?.chunkSize ?? FILE_FRAME_SIZE, Number.isFinite(negotiated) && negotiated > 0 ? negotiated : FILE_FRAME_SIZE);
      if (maximum <= HEADER_SIZE) throw asError('fileInvalid');
      const chunkSize = maximum - HEADER_SIZE;
      const idBytes = bytesForId(record.view.id);
      while (record.view.received < file.size && record.view.state === 'sending') {
        const offset = record.view.received;
        const payload = await file.slice(offset, offset + chunkSize).arrayBuffer();
        if (record.view.state !== 'sending') return;
        const frame = new Uint8Array(HEADER_SIZE + payload.byteLength);
        frame.set(MAGIC);
        frame.set(idBytes, 4);
        new DataView(frame.buffer).setBigUint64(20, BigInt(offset), false);
        frame.set(new Uint8Array(payload), HEADER_SIZE);
        // Transport waits for bufferedamountlow and keeps its own browser send queue bounded.
        await this.transport.sendBinary(frame.buffer);
        if (record.view.state !== 'sending') return;
        record.view.received += payload.byteLength;
        record.view.speed = record.view.received * 1000 / Math.max(1, performance.now() - record.started);
        this.arm(record);
        this.emit();
        // Around 256 KiB/s per file while a call is active. The delay occurs after
        // sendBinary so at most one 16 KiB application chunk is pending.
        if (this.callActive) await new Promise<void>((resolve) => {
          record.resume = resolve;
          record.paceTimer = setTimeout(() => { record.resume = undefined; resolve(); }, Math.ceil(frame.byteLength / 262_144 * 1000));
        });
      }
      if (record.view.state !== 'sending') return;
      record.view.state = 'verifying';
      this.arm(record);
      this.emit();
      await this.send('end', { id: record.view.id, size: file.size, sha256: record.digest });
    } catch { if (!TERMINAL.has(record.view.state)) this.protocolError(record, this.transport.connected ? 'fileInvalid' : 'fileInterrupted'); }
  }

  private receiveBinary(data: ArrayBuffer): void {
    if (this.disposed || !(data instanceof ArrayBuffer) || data.byteLength < HEADER_SIZE || data.byteLength > FILE_FRAME_SIZE) return;
    const frame = new Uint8Array(data);
    if (!MAGIC.every((value, index) => frame[index] === value)) return;
    const record = this.records.get(idForBytes(frame.subarray(4, 20)));
    if (!record || record.view.direction !== 'receive' || TERMINAL.has(record.view.state)) return;
    if (record.view.state !== 'receiving' || !record.buffer) { this.protocolError(record); return; }
    const offset = new DataView(data).getBigUint64(20, false);
    const length = data.byteLength - HEADER_SIZE;
    if (offset !== BigInt(record.view.received) || length === 0 || length > record.view.size - record.view.received) { this.protocolError(record); return; }
    record.buffer.set(frame.subarray(HEADER_SIZE), record.view.received);
    record.view.received += length;
    record.view.speed = record.view.received * 1000 / Math.max(1, performance.now() - record.started);
    this.arm(record);
    if (record.view.received - record.progressSent >= 256 * 1024 || record.view.received === record.view.size) {
      record.progressSent = record.view.received;
      this.notify('progress', { id: record.view.id, received: record.view.received });
    }
    this.emit();
    void this.maybeComplete(record);
  }

  private async maybeComplete(record: RecordEntry): Promise<void> {
    if (record.view.state !== 'receiving' || !record.endReceived || record.view.received !== record.view.size || !record.buffer) return;
    record.view.state = 'verifying';
    this.emit();
    try {
      const digest = await digestOf(record.buffer.buffer);
      if (record.view.state !== 'verifying' || this.disposed) return;
      if (digest !== record.digest) { this.protocolError(record, 'fileIntegrity'); return; }
      const url = URL.createObjectURL(new Blob([record.buffer], { type: 'application/octet-stream' }));
      record.view.url = url;
      record.view.state = 'complete';
      this.release(record, true);
      this.notify('ack', { id: record.view.id, sha256: digest });
      this.emit();
    } catch { this.protocolError(record, 'fileIntegrity'); }
  }

  private interrupt(): void {
    this.remote = undefined;
    for (const record of this.records.values()) this.fail(record, 'fileInterrupted');
  }
  dispose(): void {
    if (this.disposed) return;
    this.interrupt();
    this.disposed = true;
    for (const unsubscribe of this.unsubscribe) unsubscribe();
    for (const record of this.records.values()) {
      clearTimeout(record.timer);
      if (record.view.url) URL.revokeObjectURL(record.view.url);
      record.buffer = undefined;
      record.file = undefined;
    }
    this.records.clear();
    this.transfers = [];
    this.reservedMemory = 0;
    this.onChange = null;
  }
}
