import BrowserPeer from 'simple-peer/simplepeer.min.js';
import type { Instance as PeerInstance, Options as PeerOptions, SignalData } from 'simple-peer';
import type { Transport } from './transport';

export type CallState = 'idle' | 'preview' | 'inviting' | 'ringing' | 'preparing' | 'connecting' | 'active' | 'ended' | 'failed';
export interface MediaOptions {
  audio: boolean;
  video: boolean;
  audioDeviceId?: string;
  videoDeviceId?: string;
}
export interface MediaState { mic: boolean; camera: boolean; screen: boolean }
interface CallEnvelope { scope: 'call'; v: 1; sessionId: string; callId: string }
export type CallMessage = CallEnvelope & (
  | { type: 'invite' | 'accept' | 'ready' | 'hangup' }
  | { type: 'decline'; reason: 'declined' | 'busy' | 'collision' }
  | { type: 'signal'; signal: SignalData }
  | { type: 'media-state'; media: MediaState }
);

/** Injection is deliberately limited to the public simple-peer API and capture API. */
export interface CallControllerOptions {
  createPeer?: (options: PeerOptions) => PeerInstance;
  mediaDevices?: Pick<MediaDevices, 'getUserMedia'> & Partial<Pick<MediaDevices, 'getDisplayMedia'>>;
  invitationTimeoutMs?: number;
  connectionTimeoutMs?: number;
}

const MAX_SIGNALS = 128;
const MAX_SIGNAL_BYTES = 256 * 1024;
const MAX_QUEUE_BYTES = 512 * 1024;
const INVITATION_TIMEOUT = 45_000;
const CONNECTION_TIMEOUT = 60_000;
const MEDIA_END_GRACE_MS = 800;
const CALL_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ACTIVE_STATES: readonly CallState[] = ['inviting', 'ringing', 'preparing', 'connecting', 'active'];
const encoder = new TextEncoder();

function mediaError(error: unknown): string {
  const name = error instanceof Error ? error.name : '';
  if (name === 'NotAllowedError' || name === 'SecurityError') return 'call.permission';
  if (name === 'NotFoundError' || name === 'OverconstrainedError') return 'call.noDevice';
  if (name === 'NotReadableError' || name === 'AbortError') return 'call.deviceBusy';
  return 'call.mediaError';
}
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
function isSignal(value: unknown): value is SignalData {
  if (!isRecord(value)) return false;
  // Validate only the outer shape. The original object is forwarded unchanged,
  // including simple-peer's renegotiation and transceiver messages.
  if (typeof value.sdp === 'string') return (value.type === 'offer' || value.type === 'answer') && value.sdp.length <= MAX_SIGNAL_BYTES;
  if (isRecord(value.candidate)) return typeof value.candidate.candidate === 'string';
  if (value.renegotiate === true) return true;
  return isRecord(value.transceiverRequest) && typeof value.transceiverRequest.kind === 'string';
}
function size(value: unknown): number {
  try { return encoder.encode(JSON.stringify(value)).byteLength; } catch { return Infinity; }
}
function callId(): string { return crypto.randomUUID(); }

/** Optional media connection. The transport and its file channel always remain owned by Session. */
export class CallController {
  state: CallState = 'idle';
  error: string | null = null;
  localStream: MediaStream | null = null;
  remoteStream: MediaStream | null = null;
  micEnabled = false;
  cameraEnabled = false;
  screenSharing = false;
  remoteMedia: MediaState = { mic: false, camera: false, screen: false };
  startedAt: number | null = null;
  onChange: () => void = () => {};

  private readonly createPeer: (options: PeerOptions) => PeerInstance;
  private readonly devices: CallControllerOptions['mediaDevices'];
  private readonly invitationTimeout: number;
  private readonly connectionTimeout: number;
  private readonly unsubscribe: (() => void)[];
  private peer: PeerInstance | null = null;
  private id: string | null = null;
  private accepted = false;
  private remoteReady = false;
  private options: MediaOptions = { audio: false, video: false };
  private previewOptions: MediaOptions | null = null;
  private owned = new Set<MediaStreamTrack>();
  private outgoing: SignalData[] = [];
  private incoming: SignalData[] = [];
  private queuedBytes = 0;
  private timer: ReturnType<typeof setTimeout> | undefined;
  private peerErrorTimer: ReturnType<typeof setTimeout> | undefined;
  private generation = 0;
  private mediaGeneration = 0;
  private trackGenerations = { audio: 0, video: 0 };
  private endedIds: string[] = [];
  private invitations: number[] = [];
  private disposed = false;
  private restoreCamera = false;
  private restoringScreen = false;
  private screenPending = false;
  private sentMessages: Promise<void> = Promise.resolve();
  private pendingSignals = 0;
  private pendingSignalBytes = 0;
  private receivedSignals: number[] = [];

  constructor(private readonly transport: Transport, options: CallControllerOptions = {}) {
    this.createPeer = options.createPeer ?? ((config) => new BrowserPeer(config));
    this.devices = options.mediaDevices ?? globalThis.navigator?.mediaDevices;
    this.invitationTimeout = options.invitationTimeoutMs ?? INVITATION_TIMEOUT;
    this.connectionTimeout = options.connectionTimeoutMs ?? CONNECTION_TIMEOUT;
    this.unsubscribe = [
      transport.onMessage((message) => this.receive(message)),
      transport.onClose(() => this.finish('ended', 'call.sessionClosed')),
    ];
  }

  get callId(): string | null { return this.id; }
  get supportsScreenSharing(): boolean { return typeof this.devices?.getDisplayMedia === 'function'; }
  get inCall(): boolean { return ACTIVE_STATES.includes(this.state); }
  get cameraRequested(): boolean { return this.screenSharing ? this.restoreCamera : this.cameraEnabled; }

  async preview(options: MediaOptions): Promise<void> {
    if (this.disposed || ['inviting', 'preparing', 'connecting', 'active'].includes(this.state)) return;
    this.error = null;
    const generation = this.generation;
    try {
      await this.prepareMedia(options, generation);
      if (this.generation !== generation || this.disposed) return;
      if (this.state !== 'ringing') this.state = 'preview';
      this.changed();
    } catch (error) {
      if (generation !== this.generation || this.disposed) return;
      this.error = mediaError(error); this.changed();
    }
  }

  async invite(options: MediaOptions): Promise<void> {
    if (this.state === 'ringing') return this.accept(options);
    if (this.disposed || this.inCall) return;
    if (!this.transport.connected) { this.error = 'call.sessionClosed'; this.changed(); return; }
    this.resetAttempt();
    this.id = callId();
    this.options = { ...options };
    this.state = 'inviting';
    this.armTimeout(this.invitationTimeout);
    this.changed();
    await this.send('invite');
  }

  async accept(options: MediaOptions): Promise<void> {
    if (this.state !== 'ringing' || !this.id || this.disposed) return;
    const generation = this.generation;
    this.options = { ...options };
    this.accepted = true;
    this.state = 'preparing';
    this.armTimeout(this.connectionTimeout);
    this.changed();
    await this.send('accept');
    if (this.accepted && generation === this.generation) await this.preparePeer();
  }

  decline(): void {
    if (this.state !== 'ringing') return;
    void this.send('decline', { reason: 'declined' });
    this.finish('ended', null);
  }

  hangup(): void {
    if (this.id && this.inCall) void this.send('hangup');
    this.finish('ended', null);
  }

  async toggleMic(): Promise<void> {
    if (!this.localStream || !['preview', 'preparing', 'connecting', 'active'].includes(this.state)) return;
    const tracks = this.localStream.getAudioTracks();
    if (tracks.length) {
      this.micEnabled = !this.micEnabled;
      for (const track of tracks) track.enabled = this.micEnabled;
      this.options.audio = this.micEnabled;
      this.previewOptions = null;
      this.broadcastMedia();
      return;
    }
    await this.changeTrack('audio', true, this.options.audioDeviceId);
  }

  async toggleCamera(): Promise<void> {
    if (!this.localStream || !['preview', 'preparing', 'connecting', 'active'].includes(this.state)) return;
    if (this.screenSharing) await this.stopScreen();
    await this.changeTrack('video', !this.cameraEnabled, this.options.videoDeviceId);
  }

  async selectDevices(options: MediaOptions): Promise<void> {
    this.options = { ...options };
    if (!this.localStream || !['preview', 'preparing', 'connecting', 'active'].includes(this.state)) return;
    // Capture only the explicitly selected kinds. Preserve screen capture while
    // changing microphone; a selected camera is restored when sharing ends.
    await this.changeTrack('audio', options.audio, options.audioDeviceId);
    const audioError = this.error;
    if (this.screenSharing) { this.restoreCamera = options.video; return; }
    await this.changeTrack('video', options.video, options.videoDeviceId);
    if (audioError) { this.error = audioError; this.changed(); }
  }

  async shareScreen(): Promise<void> {
    if (this.screenSharing) { await this.stopScreen(); return; }
    if (this.screenPending || this.restoringScreen || !this.peer || !['connecting', 'active'].includes(this.state)) return;
    if (!this.supportsScreenSharing) { this.error = 'call.screenUnsupported'; this.changed(); return; }
    const generation = this.generation;
    const trackGeneration = ++this.trackGenerations.video;
    this.screenPending = true;
    let acquired: MediaStreamTrack | null = null;
    try {
      // Keep this call before any await: browsers require a direct user gesture.
      const capture = await this.devices!.getDisplayMedia!({ video: { frameRate: { ideal: 15, max: 30 } }, audio: false });
      if (generation !== this.generation || trackGeneration !== this.trackGenerations.video || !this.peer || this.disposed) {
        capture.getTracks().forEach((track) => track.stop()); return;
      }
      const screen = capture.getVideoTracks()[0];
      capture.getTracks().filter((track) => track !== screen).forEach((track) => track.stop());
      if (!screen) return;
      acquired = screen;
      this.restoreCamera = this.cameraEnabled;
      this.owned.add(screen);
      this.swapTrack('video', screen);
      acquired = null;
      this.screenSharing = true;
      this.cameraEnabled = false;
      screen.onended = () => { void this.stopScreen(); };
      this.error = null;
      this.broadcastMedia();
    } catch (error) {
      if (acquired) { this.owned.delete(acquired); acquired.stop(); }
      if (generation !== this.generation || this.disposed) return;
      this.error = error instanceof Error && ['NotAllowedError', 'AbortError', 'SecurityError'].includes(error.name)
        ? 'screenDenied' : 'screenFailed';
      this.changed();
    } finally { this.screenPending = false; }
  }

  dispose(): void {
    if (this.disposed) return;
    this.hangup();
    this.disposed = true;
    this.unsubscribe.forEach((unsubscribe) => unsubscribe());
    this.onChange = () => {};
  }

  private changed(): void { if (!this.disposed) this.onChange(); }

  private async prepareMedia(options: MediaOptions, generation: number): Promise<void> {
    const same = this.previewOptions && JSON.stringify(options) === JSON.stringify(this.previewOptions)
      && this.localStream?.getTracks().every((track) => track.readyState === 'live');
    if (same) { this.options = { ...options }; return; }
    const mediaGeneration = ++this.mediaGeneration;
    const stream = await this.capture(options);
    if (this.disposed || generation !== this.generation || mediaGeneration !== this.mediaGeneration) {
      stream.getTracks().forEach((track) => track.stop());
      return;
    }
    this.stopOwned();
    this.localStream = stream;
    this.options = { ...options };
    this.previewOptions = { ...options };
    for (const track of stream.getTracks()) { this.owned.add(track); this.watchTrack(track); }
    this.micEnabled = stream.getAudioTracks().some((track) => track.enabled);
    this.cameraEnabled = stream.getVideoTracks().some((track) => track.enabled);
    this.changed();
  }

  private async capture(options: MediaOptions): Promise<MediaStream> {
    if (!options.audio && !options.video) return new MediaStream();
    if (!this.devices?.getUserMedia) throw new DOMException('Capture unavailable', 'NotFoundError');
    return this.devices.getUserMedia({
      audio: options.audio ? {
        echoCancellation: true, noiseSuppression: true, autoGainControl: true,
        ...(options.audioDeviceId ? { deviceId: { exact: options.audioDeviceId } } : {}),
      } : false,
      video: options.video ? {
        width: { ideal: 1280 }, height: { ideal: 720 }, frameRate: { ideal: 30 },
        ...(options.videoDeviceId ? { deviceId: { exact: options.videoDeviceId } } : {}),
      } : false,
    });
  }

  private async preparePeer(): Promise<void> {
    if (!this.accepted || this.peer || !this.id) return;
    const generation = this.generation;
    const id = this.id;
    try {
      await this.prepareMedia(this.options, generation);
      if (generation !== this.generation || !this.accepted || this.id !== id || this.peer || this.disposed) return;
      // The browser distribution includes the stream shims, and these options
      // override simple-peer's default public STUN configuration on BOTH sides.
      const peer = this.createPeer({
        initiator: this.transport.isCreator,
        trickle: true,
        config: { iceServers: [] },
        ...(this.localStream?.getTracks().length ? { stream: this.localStream } : {}),
      });
      this.peer = peer;
      const current = () => this.peer === peer && this.generation === generation;
      peer.on('signal', (signal: SignalData) => {
        if (!current()) return;
        if (!isSignal(signal) || size(signal) > MAX_SIGNAL_BYTES) { this.fail('call.signalLimit'); return; }
        if (!this.remoteReady) { this.enqueue(this.outgoing, signal); return; }
        void this.send('signal', { signal });
      });
      peer.on('stream', (stream: MediaStream) => {
        if (!current()) return;
        this.remoteStream = stream;
        this.changed();
      });
      peer.on('track', (_track: MediaStreamTrack, stream: MediaStream) => {
        if (!current()) return;
        this.remoteStream = stream;
        this.changed();
      });
      peer.on('connect', () => {
        if (!current()) return;
        this.state = 'active';
        this.startedAt = Date.now();
        clearTimeout(this.timer);
        this.changed();
      });
      peer.on('error', () => {
        if (!current() || this.peerErrorTimer) return;
        // Media and persistent control use separate connections. A normal
        // remote destroy can surface a media error before its control hangup.
        // Allow that authenticated hangup to settle before reporting failure.
        this.peerErrorTimer = setTimeout(() => {
          this.peerErrorTimer = undefined;
          if (current()) this.fail('call.connectionFailed');
        }, MEDIA_END_GRACE_MS);
      });
      peer.on('close', () => { if (current() && !this.peerErrorTimer) this.finish('ended', null); });
      this.state = 'connecting';
      await this.send('ready');
      if (!current()) return;
      this.broadcastMedia();
      for (const signal of this.incoming.splice(0)) {
        this.queuedBytes -= size(signal);
        peer.signal(signal);
      }
      this.flushSignals();
      this.changed();
    } catch (error) { if (generation === this.generation) this.fail(mediaError(error)); }
  }

  private receive(message: Record<string, unknown>): void {
    if (this.disposed || message.scope !== 'call' || message.v !== 1 || message.sessionId !== this.transport.sessionId
      || typeof message.callId !== 'string' || !CALL_ID.test(message.callId) || size(message) > MAX_SIGNAL_BYTES + 1024) return;
    const id = message.callId;
    if (this.endedIds.includes(id)) return;
    if (message.type === 'invite') { this.receiveInvite(id); return; }
    if (id !== this.id || !this.inCall) return;
    if (message.type === 'hangup') { this.finish('ended', null); return; }
    if (message.type === 'decline' && ['inviting', 'preparing', 'connecting'].includes(this.state)) {
      if (message.reason !== 'declined' && message.reason !== 'busy' && message.reason !== 'collision') return;
      // B may receive the collision decline before A's winning invitation.
      // Keep B's explicit consent only until the ordered winner invite follows.
      if (message.reason === 'collision' && !this.transport.isCreator && this.state === 'inviting') return;
      this.finish('ended', message.reason === 'busy' ? 'call.busy' : 'call.declined');
      return;
    }
    if (message.type === 'accept' && this.state === 'inviting') {
      this.accepted = true;
      this.state = 'preparing';
      this.armTimeout(this.connectionTimeout);
      this.changed();
      void this.preparePeer();
      return;
    }
    if (!this.accepted) return;
    if (message.type === 'ready' && ['preparing', 'connecting', 'active'].includes(this.state)) {
      this.remoteReady = true;
      this.flushSignals();
    } else if (message.type === 'signal' && isSignal(message.signal) && size(message.signal) <= MAX_SIGNAL_BYTES) {
      if (!['preparing', 'connecting', 'active'].includes(this.state)) return;
      const now = performance.now();
      this.receivedSignals = this.receivedSignals.filter((time) => now - time < 60_000);
      if (this.receivedSignals.length >= 512) { this.fail('call.signalLimit'); return; }
      this.receivedSignals.push(now);
      if (!this.peer) { this.enqueue(this.incoming, message.signal); return; }
      try { this.peer.signal(message.signal); } catch { this.fail('call.connectionFailed'); }
    } else if (message.type === 'media-state' && isRecord(message.media)) {
      const media = message.media;
      if (typeof media.mic !== 'boolean' || typeof media.camera !== 'boolean' || typeof media.screen !== 'boolean') return;
      this.remoteMedia = { mic: media.mic, camera: media.camera, screen: media.screen };
      this.changed();
    }
  }

  private receiveInvite(id: string): void {
    if (id === this.id) return;
    const now = performance.now();
    this.invitations = this.invitations.filter((time) => now - time < 60_000);
    if (this.invitations.length >= 8) return;
    this.invitations.push(now);
    if (this.state === 'inviting') {
      if (this.transport.isCreator) { void this.sendFor(id, 'decline', { reason: 'collision' }); return; }
      // Both invitations are explicit local consent. A's invitation wins,
      // regardless of which invite arrives first over the ordered channel.
      const consent = { ...this.options };
      this.abandonId();
      this.resetAttempt();
      this.id = id;
      this.state = 'ringing';
      void this.accept(consent);
      return;
    }
    if (this.inCall) { void this.sendFor(id, 'decline', { reason: 'busy' }); return; }
    this.resetAttempt();
    this.id = id;
    this.state = 'ringing';
    this.armTimeout(this.invitationTimeout);
    this.changed();
  }

  private enqueue(queue: SignalData[], signal: SignalData): void {
    const bytes = size(signal);
    if (this.incoming.length + this.outgoing.length >= MAX_SIGNALS || this.queuedBytes + bytes > MAX_QUEUE_BYTES) {
      this.fail('call.signalLimit'); return;
    }
    queue.push(signal);
    this.queuedBytes += bytes;
  }

  private flushSignals(): void {
    if (!this.remoteReady || !this.peer || !this.accepted) return;
    for (const signal of this.outgoing.splice(0)) {
      this.queuedBytes -= size(signal);
      void this.send('signal', { signal });
    }
  }

  private async changeTrack(kind: 'audio' | 'video', enabled: boolean, deviceId?: string): Promise<void> {
    if (!this.localStream) return;
    const generation = this.generation;
    const trackGeneration = ++this.trackGenerations[kind];
    let replacement: MediaStreamTrack | null = null;
    try {
      if (enabled) {
        const capture = await this.capture({
          audio: kind === 'audio', video: kind === 'video',
          ...(kind === 'audio' && deviceId ? { audioDeviceId: deviceId } : {}),
          ...(kind === 'video' && deviceId ? { videoDeviceId: deviceId } : {}),
        });
        if (generation !== this.generation || trackGeneration !== this.trackGenerations[kind] || !this.localStream || this.disposed) {
          capture.getTracks().forEach((track) => track.stop()); return;
        }
        replacement = capture.getTracks().find((track) => track.kind === kind) ?? null;
        for (const track of capture.getTracks()) if (track !== replacement) track.stop();
        if (!replacement) return;
        this.owned.add(replacement);
        this.watchTrack(replacement);
      }
      this.swapTrack(kind, replacement);
      replacement = null;
      if (kind === 'audio') { this.micEnabled = enabled; this.options.audio = enabled; }
      else { this.cameraEnabled = enabled; this.options.video = enabled; }
      this.previewOptions = null;
      this.error = null;
      this.broadcastMedia();
    } catch (error) {
      if (replacement) { this.owned.delete(replacement); replacement.onended = null; replacement.stop(); }
      if (generation !== this.generation || trackGeneration !== this.trackGenerations[kind] || this.disposed) return;
      this.error = mediaError(error); this.changed();
    }
  }

  private swapTrack(kind: 'audio' | 'video', replacement: MediaStreamTrack | null): void {
    const stream = this.localStream!;
    const previous = stream.getTracks().find((track) => track.kind === kind);
    if (this.peer) {
      if (previous && replacement) this.peer.replaceTrack(previous, replacement, stream);
      else if (previous) this.peer.removeTrack(previous, stream);
      else if (replacement) this.peer.addTrack(replacement, stream);
    }
    if (previous) {
      previous.onended = null;
      stream.removeTrack(previous);
      this.owned.delete(previous);
      previous.stop();
    }
    if (replacement) stream.addTrack(replacement);
  }

  private async stopScreen(): Promise<void> {
    if (!this.screenSharing || this.restoringScreen) return;
    this.restoringScreen = true;
    const restore = this.restoreCamera;
    this.screenSharing = false;
    try {
      // Remove even an ended screen track before reacquisition, so a denied or
      // missing webcam cannot leave a dead screen sender advertised as live.
      this.swapTrack('video', null);
      this.cameraEnabled = false;
      this.broadcastMedia();
      if (restore) await this.changeTrack('video', true, this.options.videoDeviceId);
    } finally { this.restoringScreen = false; }
  }

  private watchTrack(track: MediaStreamTrack): void {
    track.onended = () => {
      if (!this.owned.has(track) || !this.localStream) return;
      try { this.peer?.removeTrack(track, this.localStream); } catch { /* Peer may be closing. */ }
      this.localStream.removeTrack(track);
      this.owned.delete(track);
      if (track.kind === 'audio') this.micEnabled = false;
      else this.cameraEnabled = false;
      this.previewOptions = null;
      this.error = 'call.deviceEnded';
      this.broadcastMedia();
    };
  }

  private broadcastMedia(): void {
    if (this.accepted && this.id) void this.send('media-state', { media: {
      mic: this.micEnabled, camera: this.cameraEnabled, screen: this.screenSharing,
    } });
    this.changed();
  }

  private send(type: CallMessage['type'], extra: Record<string, unknown> = {}): Promise<void> {
    return this.id ? this.sendFor(this.id, type, extra) : Promise.resolve();
  }

  private sendFor(id: string, type: CallMessage['type'], extra: Record<string, unknown>): Promise<void> {
    const message = { scope: 'call', v: 1, sessionId: this.transport.sessionId, callId: id, type, ...extra };
    const signalBytes = type === 'signal' ? size(extra.signal) : 0;
    if (type === 'signal') {
      if (this.pendingSignals >= MAX_SIGNALS || this.pendingSignalBytes + signalBytes > MAX_QUEUE_BYTES) {
        this.fail('call.signalLimit'); return Promise.resolve();
      }
      this.pendingSignals++;
      this.pendingSignalBytes += signalBytes;
    }
    // Preserve ready/signal/hangup order even when transport fragmentation waits
    // for bufferedamountlow. The shared transport owns fragmentation bounds.
    this.sentMessages = this.sentMessages.then(async () => {
      try {
        if (type !== 'hangup' && type !== 'decline' && this.id !== id) return;
        if (this.transport.connected) await this.transport.send(message);
      } finally {
        if (type === 'signal') { this.pendingSignals--; this.pendingSignalBytes -= signalBytes; }
      }
    }).catch(() => { if (this.id === id && this.inCall) this.finish('failed', 'call.sessionClosed'); });
    return this.sentMessages;
  }

  private armTimeout(duration: number): void {
    clearTimeout(this.timer);
    this.timer = setTimeout(() => this.fail('call.timeout'), duration);
  }

  private fail(error: string): void {
    if (this.id) void this.send('hangup');
    this.finish('failed', error);
  }

  private abandonId(): void {
    if (this.id) this.endedIds.push(this.id);
    if (this.endedIds.length > 64) this.endedIds.shift();
    this.id = null;
  }

  private resetAttempt(): void {
    clearTimeout(this.timer);
    clearTimeout(this.peerErrorTimer);
    this.peerErrorTimer = undefined;
    this.generation++;
    this.mediaGeneration++;
    this.trackGenerations.audio++;
    this.trackGenerations.video++;
    this.accepted = false;
    this.remoteReady = false;
    this.incoming = [];
    this.outgoing = [];
    this.queuedBytes = 0;
    this.receivedSignals = [];
    this.remoteStream = null;
    this.remoteMedia = { mic: false, camera: false, screen: false };
    this.startedAt = null;
    this.error = null;
  }

  private stopOwned(): void {
    for (const track of this.owned) { track.onended = null; track.stop(); }
    this.owned.clear();
  }

  private finish(state: 'ended' | 'failed', error: string | null): void {
    this.abandonId();
    this.resetAttempt();
    const peer = this.peer;
    this.peer = null;
    peer?.destroy();
    this.stopOwned();
    this.localStream = null;
    this.previewOptions = null;
    this.micEnabled = false;
    this.cameraEnabled = false;
    this.screenSharing = false;
    this.restoreCamera = false;
    this.screenPending = false;
    this.state = state;
    this.error = error;
    this.changed();
  }
}
